package ro.leo.visual;
import java.io.*;import java.net.*;import java.util.regex.*;
/** One on-demand metadata sample, separate from playback; at most 256 KiB of audio. */
final class IcyMetadata {
 static String sample(String raw)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(PocketStore.url(raw)).openConnection();c.setConnectTimeout(6000);c.setReadTimeout(8000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Icy-MetaData","1");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());int interval;try{interval=Integer.parseInt(c.getHeaderField("icy-metaint"));}catch(Exception e){return "No ICY metadata provided";}if(interval<1||interval>262144)throw new IOException("ICY interval exceeds preview limit");try(InputStream in=c.getInputStream()){int left=interval;byte[] b=new byte[4096];while(left>0){int n=in.read(b,0,Math.min(left,b.length));if(n<0)throw new EOFException();left-=n;}int blocks=in.read();if(blocks<0)throw new EOFException();int size=blocks*16;byte[] metadata=new byte[size];for(int done=0;done<size;){int n=in.read(metadata,done,size-done);if(n<0)throw new EOFException();done+=n;}String text=new String(metadata,"UTF-8").replace("\0","");Matcher m=Pattern.compile("StreamTitle='(.*?)';",Pattern.DOTALL).matcher(text);return m.find()?UiText.preview(m.group(1),500):"No current track title";}}finally{c.disconnect();}}
}
